// src/pages/Community.js

import { useNavigate } from "react-router-dom";
import { useState } from "react";

function Community() {
  const navigate = useNavigate();

  const [meetings, setMeetings] = useState([
    {
      title: "노르웨이의 숲",
      date: "2026-03-12",
      time: "19:00",
      people: "5/8명",
      mood: "badge1",
    },

    {
      title: "데미안",
      date: "2026-03-13",
      time: "21:00",
      people: "3/6명",
      mood: "badge2",
    },

    {
      title: "어린왕자",
      date: "2026-03-14",
      time: "20:00",
      people: "7/10명",
      mood: "badge3",
    },
  ]);

  const [showForm, setShowForm] =
    useState(false);

  const [newMeeting, setNewMeeting] =
    useState({
      title: "",
      date: "",
      time: "",
      maxPeople: "",
      mood: "badge1",
    });

  const getMoodText = (mood) => {
    if (mood === "badge1")
      return "깊게 토론해요";

    if (mood === "badge2")
      return "부담없이 참여해요";

    return "함께 이야기해요";
  };

  const createMeeting = () => {
    if (
      !newMeeting.title ||
      !newMeeting.date ||
      !newMeeting.time
    )
      return;

    const newItem = {
      title: newMeeting.title,
      date: newMeeting.date,
      time: newMeeting.time,
      people: `1/${newMeeting.maxPeople}명`,
      mood: newMeeting.mood,
    };

    setMeetings([
      newItem,
      ...meetings,
    ]);

    setShowForm(false);

    setNewMeeting({
      title: "",
      date: "",
      time: "",
      maxPeople: "",
      mood: "badge1",
    });
  };

  return (
    <div className="page">
      <div className="community-header">
        <div className="logo">
          READLY
        </div>

        <button
          className="create-btn"
          onClick={() =>
            setShowForm(!showForm)
          }
        >
          + 모임 만들기
        </button>
      </div>

      <div className="community-guide">
        모임 시작 10분 전까지
        참여할 수 있어요 📚
      </div>

      {showForm && (
        <div className="create-form">
          <input
            placeholder="책 제목"
            value={newMeeting.title}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                title: e.target.value,
              })
            }
          />

          <input
            type="date"
            value={newMeeting.date}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                date: e.target.value,
              })
            }
          />

          <input
            type="time"
            value={newMeeting.time}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                time: e.target.value,
              })
            }
          />

          <input
            type="number"
            placeholder="최대 인원"
            value={newMeeting.maxPeople}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                maxPeople:
                  e.target.value,
              })
            }
          />

          <select
            value={newMeeting.mood}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                mood: e.target.value,
              })
            }
          >
            <option value="badge1">
              깊게 토론해요
            </option>

            <option value="badge2">
              부담없이 참여해요
            </option>

            <option value="badge3">
              함께 이야기해요
            </option>
          </select>

          <button
            className="submit-btn"
            onClick={createMeeting}
          >
            모임 생성하기
          </button>
        </div>
      )}

      <div className="meeting-list">
        {meetings.map(
          (meeting, index) => {
            const today =
              new Date();

            const meetingDate =
              new Date(
                `${meeting.date}T${meeting.time}`
              );

            const isFuture =
              meetingDate > today;

            return (
              <div
                className="meeting-card"
                key={index}
              >
                <div className="meeting-top">
                  <div>
                    <div className="meeting-book">
                      📖{" "}
                      {meeting.title}
                    </div>

                    <div className="meeting-time">
                      {meeting.date} ·{" "}
                      {meeting.time}
                    </div>
                  </div>

                  <div
                    className={
                      meeting.mood
                    }
                  >
                    {getMoodText(
                      meeting.mood
                    )}
                  </div>
                </div>

                <div className="meeting-bottom">
                  <div className="meeting-member">
                    👥{" "}
                    {meeting.people}
                  </div>

                  {isFuture ? (
                    <div className="before-start">
                      시작 전
                    </div>
                  ) : (
                    <button
                      className="join-btn"
                      onClick={() =>
                        navigate(
                          "/meeting",
                          {
                            state: {
                              title:
                                meeting.title,
                              mood:
                                meeting.mood,
                            },
                          }
                        )
                      }
                    >
                      참여하기
                    </button>
                  )}
                </div>
              </div>
            );
          }
        )}
      </div>
    </div>
  );
}

export default Community;
